    def test_page_to_rd_and_findings(self):
        ctx = make_repo()
        (ctx.repo / "R/EDI/man/InferenceCountZeroInflatedNegBin.Rd").write_text(
            "% Please edit documentation in R/foo.R\n\\name{InferenceCountZeroInflatedNegBin}\n"
            "\\alias{InferenceCountZeroInflatedNegBin}\n")
