class Spelling(unittest.TestCase):
    def test_seed_and_identifiers(self):
        words = [{"word": "Foo", "found": ["a.Rd:1"]}, {"word": "teh", "found": ["a.Rd:2"]},
                 {"word": "Agresti", "found": ["a.Rd:3"]}, {"word": "heteroskedastic", "found": ["a.Rd:4", "b.Rd:1"]}]
        add, report = rd.split_spelling(words, {"Foo"}, seeding=True)
        self.assertEqual(sorted(add), ["Agresti", "Foo", "heteroskedastic"])
        self.assertEqual([w["word"] for w in report], ["teh"])             # likely typo stays reported
        add2, report2 = rd.split_spelling(words, {"Foo"}, seeding=False)
        self.assertEqual(add2, ["Foo"])
        self.assertEqual(len(report2), 3)

    def test_merge(self):
        text, new = rd.merge_wordlist("beta\nAlpha\n", ["alpha2", "beta"])
        self.assertEqual(text, "Alpha\nalpha2\nbeta\n")
        self.assertEqual(new, ["alpha2"])


class Units(unittest.TestCase):
    def test_failing_example_chosen_regardless_of_rotation(self):
        ctx = make_repo()
        u = rd.units(ctx)
        rel = "R/EDI/man/Foo.Rd"
        # recorded as audited, unchanged, and not in this week's rotation slice
        manifest = {"units": {rel: {"hash": u[rel]["hash"], "deps": u[rel]["deps"],
                                    "audited_at": "2026-11-14T06:00:00+00:00"}}}
        chosen, _, _ = ac.select_units(u, manifest, "auto", 10 ** 6, NOW)
        self.assertEqual(chosen, [])
        sh.write_json(ctx.workdir / "rd_failing.json", {rel: {"problems": ["error: boom"], "parts": ["full"]}})
        u2 = rd.units(ctx)
        chosen, reasons, _ = ac.select_units(u2, manifest, "auto", 10 ** 6, NOW)
        self.assertEqual(chosen, [rel])
        fe = u2[rel]["context"]["failing_example"]
        self.assertEqual(fe["examples_source"], [{"file": "R/EDI/R/foo.R", "lines": "5-7"}])
        self.assertEqual(fe["failing_part"], "inside \\donttest")
        self.assertIn("Foo$new(n)", fe["usage"])
        # a week later, still failing with the same message: still chosen
        manifest["units"][rel]["hash"] = u2[rel]["hash"]
        ctx.now = NOW + dt.timedelta(days=7)
        self.assertEqual(ac.select_units(rd.units(ctx), manifest, "auto", 10 ** 6, ctx.now)[0], [rel])


class Apply(unittest.TestCase):
    REL = "R/EDI/man/Foo.Rd"

    def setUp(self):
        self.ctx = make_repo()
        sh.write_json(self.ctx.workdir / "rd_failing.json", {self.REL: {"problems": ["error"], "parts": ["full"]}})

    def result(self, **f):
        return [{"units_checked": [self.REL], "findings": [{"unit": self.REL, "text": "t", **f}],
                 "_batch": "b001", "_units": [self.REL]}]

    def go(self, results, run):
        return rd.apply(self.ctx, results, [], run=run, extract=fake_extract, roxygen=NO_ROXYGEN,
                        checkrd=lambda ctx, p: {})

    def src(self):
        return (self.ctx.repo / "R/EDI/R/foo.R").read_text()

    def test_seed_one_passes_seed_three_fails_not_applied(self):
        block = "\\donttest{\ny = rpois(10, 2)\nx = Foo$new(n = 10)\n}\nx0 = Foo$new(n = 2)"
        run = FakeRunner({("full", 3): {**ok_run(), "error": "the response has no zeros"}})
        parts = self.go(self.result(kind="example-fix", example_block=block, cause="no zeros"), run)
        self.assertEqual(self.src(), FOO_R)
        self.assertEqual(parts["applied"], [])
        self.assertIn("seed 3 of 5", parts["human"][0])
        self.assertEqual(parts["proposed"], [])

    def test_plain_part_too_slow_rejected(self):
        block = "x = Foo$new(n = 10)\nx$fit()"
        parts = self.go(self.result(kind="example-fix", example_block=block, cause="slow"),
                        FakeRunner({"cran": ok_run(4.5, 4.5)}))
        self.assertEqual(self.src(), FOO_R)
        self.assertIn("4.5 s elapsed", parts["human"][0])

    def test_clean_proposal_applied_only_to_examples(self):
        block = "x = Foo$new(n = 4)\n\\donttest{\nx$fit()\n}"
        run = FakeRunner()
        parts = self.go(self.result(kind="example-fix", example_block=block, cause="n too large"), run)
        new = self.src()
        self.assertEqual(new.splitlines()[:4], FOO_R.splitlines()[:4])
        self.assertEqual(new.splitlines()[4:9], ["#' @examples", "#' x = Foo$new(n = 4)", "#' \\donttest{",
                                                 "#' x$fit()", "#' }"])
        self.assertEqual(new.splitlines()[9:], FOO_R.splitlines()[7:])
        self.assertEqual(len(parts["applied"]), 1)
        self.assertIn("n too large", parts["applied"][0])
        p = parts["proposed"][0]
        self.assertEqual(p["applied_file"], "R/EDI/R/foo.R")
        self.assertIn(p["applied_text"], new)
        self.assertEqual(sorted(s for k, s, _ in run.calls if k == "full"), [1, 2, 3, 4, 5])

    def test_hiding_and_dontrun_rules(self):
        for block, extra, why in (("try(Foo$new(n = 1))", {}, "hides"),
                                  ("\\dontrun{\nFoo$new(n = 1)\n}", {}, "allowed reasons"),
                                  ("\\donttest{\nFoo$new(n = 1)\n}", {}, "no plain code")):
            self.setUp()
            parts = self.go(self.result(kind="example-fix", example_block=block, cause="c", **extra), FakeRunner())
            self.assertEqual(self.src(), FOO_R, block)
            self.assertIn(why, parts["human"][0], block)
        self.setUp()
        parts = self.go(self.result(kind="example-fix", example_block="\\donttest{\nFoo$new(n = 1)\n}", cause="c",
                                    plain_part_reason="every constructor call takes 10 s"), FakeRunner())
        self.assertEqual(len(parts["applied"]), 1)

    def test_example_fix_for_a_page_that_did_not_fail(self):
        sh.write_json(self.ctx.workdir / "rd_failing.json", {})
        parts = self.go(self.result(kind="example-fix", example_block="Foo$new(n = 1)", cause="c"), FakeRunner())
        self.assertEqual(self.src(), FOO_R)
        self.assertEqual(len(parts["human"]), 1)

    def test_sentence_fix(self):
        parts = self.go(self.result(kind="grammar", source_file="R/EDI/R/foo.R", old_sentence="It have one method.",
                                    new_sentence="It has one method.", changes_claim=False), FakeRunner())
        self.assertIn("It has one method.", self.src())
        self.assertIn("It have help.", self.src())
        self.assertEqual(len(parts["applied"]), 1)
        self.assertIn(parts["proposed"][0]["applied_text"], self.src())

    def test_sentence_fix_rules(self):
        for f in ({"kind": "unclear", "old_sentence": "It have one method.", "new_sentence": "It has one method."},
                  {"kind": "grammar", "old_sentence": "It have one method.", "new_sentence": "It has one method.",
                   "changes_claim": True},
                  {"kind": "grammar", "old_sentence": "No such sentence.", "new_sentence": "No such sentences."}):
            self.setUp()
            parts = self.go(self.result(source_file="R/EDI/R/foo.R", **f), FakeRunner())
            self.assertEqual(self.src(), FOO_R, f)
            self.assertEqual(len(parts["human"]), 1, f)

    def test_rejected_before_is_not_reapplied(self):
        fid = rd.text_fix_id(self.REL, "grammar", "It have one method.", "It has one method.")
        self.ctx.notes.save_findings([{"id": fid, "status": "rejected"}])
        parts = self.go(self.result(kind="grammar", source_file="R/EDI/R/foo.R", old_sentence="It have one method.",
                                    new_sentence="It has one method."), FakeRunner())
        self.assertEqual(self.src(), FOO_R)
        self.assertIn("rejected them before", parts["summary"])

    def test_wordlist_seed(self):
        sh.write_json(self.ctx.workdir / "rd_wordlist.json", {"seed": True, "add": ["Foo", "Agresti"]})
        parts = self.go([], FakeRunner())
        self.assertEqual((self.ctx.repo / "R/EDI/inst/WORDLIST").read_text(), "Agresti\nFoo\n")
        self.assertIn("seeded with 2 words", parts["applied"][0])

    def test_no_r_says_so(self):
        self.ctx.notes  # noqa: B018
        parts = rd.apply(self.ctx, self.result(kind="grammar", source_file="R/EDI/R/foo.R",
                                               old_sentence="It have one method.", new_sentence="It has one method."),
                         [], roxygen=lambda repo, files: sh.run_roxygen_once(repo, files) if False else
                         {"ran": False, "ok": False, "kept": [], "reverted": [],
                          "note": "R is not available in this job, so roxygen was NOT RUN"})
        self.assertIn("roxygen was NOT RUN", parts["summary"])


class Publish(unittest.TestCase):
    """Run 44048299100 (2026-11-17, the first full rd pass): 10 applied changes, 130 spelling
    findings and 156 "Needs a human" lines made a 96,412-character report, and the publish step's
    `gh pr create --body <report>` failed with "Body is too long (maximum is 65536 characters)".
    This drives `audit_run.py publish` end to end (real git against a local bare remote, fake gh)
    and checks that every body handed to gh fits."""

    GH_MAX = 65536

    def setUp(self):
        import audit_run
        self.ar = audit_run
        self.ctx = make_repo()
        repo = self.ctx.repo
        remote = repo.parent / "remote.git"
        subprocess.run(["git", "init", "-q", "--bare", str(remote)], check=True, capture_output=True)
        subprocess.run(["git", "remote", "add", "origin", str(remote)], cwd=repo, check=True, capture_output=True)
        (repo / "R/EDI/man/Foo.Rd").write_text(FOO_RD + "% changed\n")   # something to commit
        spec = ac.spec_of(rd)
        word = lambda i: "".join(chr(97 + int(c)) for c in str(i))
        parts = {
            "summary": "- roxygen ran once and regenerated 9 Rd file(s)",
            "applied": [f"`R/EDI/R/f{i}.R` (`F{i}.Rd`): replaced the @examples block. " + "c" * 900
                        for i in range(10)],
            "mechanical": [f"unknown word `{word(i)}`: Page{i}.Rd:{i}" for i in range(130)],
            "human": [f"`page{i}.Rd` (unclear): HUMAN-{i} " + "h" * 520 for i in range(156)],
        }
        coverage = {"units in scope": 369, "mechanical findings": 130}
        self.report = ac.render_report(spec, parts, coverage, "https://run")
        work = self.ctx.workdir
        (work / "report.md").write_text(self.report)
        (work / "proposed.json").write_text("[]")
        self.calls = []

    def fake_gh(self, *args, check=True, input=None):
        self.calls.append(args)
        if args[:2] == ("pr", "create"):
            return "https://github.com/o/r/pull/7"
        return ""   # label create; pr list / issue list: nothing open

    def publish(self):
        orig = self.ar.gh
        self.ar.gh = self.fake_gh
        try:
            return self.ar.main(["publish", "--audit", "rd", "--repo", str(self.ctx.repo),
                                 "--notes", str(self.ctx.notes.root), "--work", str(self.ctx.workdir),
                                 "--changed", "true", "--findings", "true"])
        finally:
            self.ar.gh = orig

    def test_oversized_report_is_cut_before_gh(self):
        self.assertGreater(len(self.report), self.GH_MAX)     # the failing size
        self.assertEqual(self.publish(), 0)
        bodies = [c[c.index("--body") + 1] for c in self.calls if "--body" in c]
        creates = [c for c in self.calls if c[:2] == ("pr", "create")]
        self.assertEqual(len(creates), 1)
        self.assertTrue(bodies)
        for b in bodies:
            self.assertLessEqual(len(b), self.GH_MAX)
        body = creates[0][creates[0].index("--body") + 1]
        self.assertTrue(body.startswith("## Rd audit"))
        self.assertIn("### Applied changes (10)", body)
        self.assertIn("more line(s) not shown", body)
        self.assertIn("units in scope: 369", body)
        self.assertEqual(self.ctx.notes.manifest().get("open_pr"), 7)


if __name__ == "__main__":
    unittest.main(verbosity=1)
